    const reposDirectory = path.join(root, '.ploinky', 'repos');
    const declared = new Set();
    const scanRepo = (repo, repoDirectory) => {
        for (const agent of directoryNames(fsApi, repoDirectory, maxEntries)) {
            let selector;
            try {
