251	        async state(source) {
252	            if (!source.commit || !source.files) return { state: 'unpinned', bytes: 0, total: null };
253	            let bytes = 0;
254	            let complete = true;
255	            let partial = false;
256	            for (const file of source.files) {
257	                const inspected = await inspectSnapshot({ root: hfRoot, artifact: snapshotFile(source, file) });
