288	        },
289	        // Delete weights removes the whole snapshot and its bookkeeping.
290	        async remove(source) {
291	            if (!source.commit) return 0;
292	            const { dir, stateDir } = snapshotPaths({ root: hfRoot, repo: source.repo, commit: source.commit });
293	            const freed = await treeBytes(dir) + await treeBytes(stateDir);
294	            await fs.promises.rm(dir, { recursive: true, force: true });
295	            await fs.promises.rm(stateDir, { recursive: true, force: true });
296	            return freed;
297	        },
298	        // Pinning reads Hugging Face metadata only; no weights are downloaded.
299	        async pin(source) {
300	            if (source.commit && source.files) return source;
301	            const resolved = await resolveSnapshot({
302	                repo: source.repo,
303	                revision: source.revision || 'main',
304	                token: env.HF_TOKEN || '',
305	                baseUrl: hfBaseUrl,
306	            });
307	            const files = resolved.files.map((file) => ({ ...file }));
308	            return { ...source, commit: resolved.commit, files, size: files.reduce((sum, file) => sum + file.size, 0) };
309	        },
310	        // An update keeps the pin while repository and revision are unchanged.
311	        carryPin(next, previous) {
312	            if (next.commit || previous?.type !== 'hf-snapshot' || !previous.commit) return next;
313	            if (next.repo !== previous.repo || next.revision !== previous.revision) return next;
314	            return { ...next, commit: previous.commit, files: previous.files, size: previous.size };
315	        },
316	    });
317	
318	    return Object.freeze({ huggingface, ollama, 'hf-snapshot': hfSnapshot });
319	}
