rep("//   idle -> downloading -> verifying -> starting -> ready -> stopping -> idle","//   idle -> downloading | copying | verifying -> starting -> ready -> stopping -> idle")
rep("const ACTIVE_PHASES = new Set(['downloading', 'verifying', 'starting', 'loading', 'ready', 'stopping']);\nconst TRANSFER_PHASES = new Set(['downloading', 'verifying']);",
    "const ACTIVE_PHASES = new Set(['downloading', 'copying', 'verifying', 'starting', 'loading', 'ready', 'stopping']);\nconst TRANSFER_PHASES = new Set(['downloading', 'copying', 'verifying']);")
rep("""    async function weightsState(source) {
        return source ? storeFor(source).state(source) : null;
    }""","""    async function weightsState(source) {
        return source ? storeFor(source).state(source) : null;
    }

    // How the weights would be obtained and the disk that needs (C12, R4):
    // Run, its preview and the overview all use it for the disk term of
    // admission. It hashes and copies nothing.
    async function acquisitionOf(source, index = null) {
        if (!source) return { bytesNeeded: 0, files: [] };
        const store = storeFor(source);
        if (store.plan) return store.plan(source, { index });
        const disk = await store.state(source);
