    assert.equal(s.fetches.length, 1);
    assert.equal(crypto.createHash('sha256').update(fs.readFileSync(s.paths.file)).digest('hex'), SHA256);
    assert.notEqual(fs.statSync(s.paths.file).ino, fs.statSync(source).ino);
