    let release;
    let entered;
    const gate = new Promise((resolve) => { release = resolve; });
    const started = new Promise((resolve) => { entered = resolve; });
    let held = false;
    fs.promises.opendir = async (dir, options) => {
        opened += 1;
        if (dir === s.shared && !held) {
            held = true;
            entered();
            await gate;
        }
        return original(dir, options);
